use glam::DVec3;
use ingetrazo_core::offset::{offset_regions,offset_chain};
use serde_json::{json,Value};
fn main(){let a:Vec<String>=std::env::args().collect();let cases:Value=serde_json::from_slice(&std::fs::read(&a[1]).unwrap()).unwrap();let out:Vec<_>=cases.as_array().unwrap().iter().map(|c|{let points:Vec<_>=c["points"].as_array().unwrap().iter().map(|p|DVec3::new(p[0].as_f64().unwrap(),p[1].as_f64().unwrap(),p[2].as_f64().unwrap())).collect();let n=&c["normal"];let normal=DVec3::new(n[0].as_f64().unwrap(),n[1].as_f64().unwrap(),n[2].as_f64().unwrap());let d=c["distance"].as_f64().unwrap();if c["chain"]==true {match offset_chain(&points,normal,d){Ok(p)=>json!({"chain":p.iter().map(|p|p.to_array()).collect::<Vec<_>>()}),Err(e)=>json!({"error":e})}}else{match offset_regions(&points,normal,d){Ok(cells)=>json!({"regions":cells.iter().map(|c|json!({"outer":c.outer.iter().map(|p|p.to_array()).collect::<Vec<_>>(),"holes":c.holes.iter().map(|h|h.iter().map(|p|p.to_array()).collect::<Vec<_>>()).collect::<Vec<_>>()})).collect::<Vec<_>>()}),Err(e)=>json!({"error":e})}}}).collect();std::fs::write(&a[2],serde_json::to_vec_pretty(&out).unwrap()).unwrap();}
